loadmodule "modules/sl/sl.so"
loadmodule "modules/usrloc/usrloc.so"
loadmodule "modules/registrar/registrar.so"
loadmodule "modules/tm/tm.so"
loadmodule "modules/acc/acc.so"
loadmodule "modules/uac\_redirect/uac\_redirect.so"

modparam("usrloc", "working\_mode\_preset", "single-instance-no-db")

route{
	if (is\_myself("$rd")) {

		if ($rm=="REGISTER") {
			save("location");
			exit;
		};

		if (!lookup("location")) {
			sl\_send\_reply(404, "Not Found");
			exit;
		};
	}

	t\_on\_failure("do\_redirect");

	if (!t\_relay()) {
		sl\_reply\_error();
	};
}

failure\_route[do\_redirect] {
	if (get\_redirects(3, 1))
		t\_relay();
}
